 "new_string": "def transform(grid):
    """Extend each colored cross along its row and column.

    A cross's own adjacent 3-arms are carried through; other original
    non-background cells block its rays. Original markers/centers stay fixed.
    Vertical rays take precedence at empty line intersections.
    """
    h = len(grid)
    if not h:
        return []
    w = len(grid[0])
    centers = [(r, c, grid[r][c])
               for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 3)]
    out = [row[:] for row in grid]

    def ray(r, c, dr, dc, color, own_arm):
        i, j = r + dr, c + dc
        while 0 <= i < h and 0 <= j < w:
            if grid[i][j] == 3:
                if (i, j) == own_arm:
                    # Keep this cross's own arm marker, but the ray continues.
                    pass
                else:
                    break
            elif grid[i][j] != 0:
                break
            else:
                out[i][j] = color
            i += dr
            j += dc

    # Horizontal then vertical so vertical strokes win at intersections.
    for r, c, color in centers:
        for dc in (-1, 1):
            ray(r, c, 0, dc, color, (r, c + dc))
    for r, c, color in centers:
        for dr in (-1, 1):
            ray(r, c, dr, 0, color, (r + dr, c))
    return out
