    centers = [(r, c, grid[r][c])
               for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 3)]
    # Draw horizontal rays only across the grid section between the nearest
    # existing 3-markers/objects; likewise vertical strokes are bounded by
    # the nearest marked cells. The color continues through empty cells but
    # stops before a distinct cross marker on the same line.
    out = [row[:] for row in grid]
    original = [row[:] for row in grid]
    for r, c, color in centers:
        # Continue along the full row/column; crossings of unrelated colors
        # are overwritten by the originating cross's ray, except 3 markers.
        for j in range(w):
            if original[r][j] == 0 or (original[r][j] not in (0, 3) and j != c):
                out[r][j] = color
        for i in range(h):
            if original[i][c] == 0 or (original[i][c] not in (0, 3) and i != r):
                out[i][c] = color
