            if original[r][j] == 3:
                break
        for j in range(c + 1, w):
            if original[r][j] == 3:
                break
        for i in range(r - 1, -1, -1):
            if original[i][c] == 3:
                break
        for i in range(r + 1, h):
            if original[i][c] == 3:
                break
    return out
