 "new_string": "def transform(grid):
    """Extend the colored cross centers in four directions.

    Each center's own 3 arms are transparent to its rays; other 3 markers
    block rays. Empty-centered 3-crosses create a clear vertical track.
    """
    h = len(grid)
    if not h:
        return []
    w = len(grid[0])
    original = [row[:] for row in grid]
    out = [row[:] for row in grid]
    centers = [(r, c, grid[r][c])
               for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 3)]

    def trace(r, c, dr, dc, color):
        own_arms = {(r-1,c), (r+1,c), (r,c-1), (r,c+1)}
        i, j = r + dr, c + dc
        while 0 <= i < h and 0 <= j < w:
            if original[i][j] == 3 and (i,j) not in own_arms:
                break
            if original[i][j] not in (0, 3):
                break
            if original[i][j] == 0:
                out[i][j] = color
            i += dr
            j += dc

    # Horizontal first; vertical strokes win where colored rays intersect.
    for r, c, color in centers:
        trace(r, c, 0, -1, color)
        trace(r, c, 0, 1, color)
    for r, c, color in centers:
        trace(r, c, -1, 0, color)
        trace(r, c, 1, 0, color)

    # Empty center + four 3 arms denotes a vertical blank track.
    for r in range(1, h-1):
        for c in range(1, w-1):
            if (original[r][c] == 0 and original[r-1][c] == 3
                    and original[r+1][c] == 3 and original[r][c-1] == 3
                    and original[r][c+1] == 3):
                for i in range(h):
                    if original[i][c] == 0:
                        out[i][c] = 0
    return out
