 "content": "def transform(grid):
    """Extend colored cross rays, preserving markers and respecting blockers."""
    h = len(grid)
    if not h:
        return []
    w = len(grid[0])
    original = [row[:] for row in grid]
    out = [row[:] for row in grid]
    centers = [(r, c, original[r][c])
               for r in range(h) for c in range(w)
               if original[r][c] not in (0, 3)]

    def ray(r, c, dr, dc, color):
        i, j = r + dr, c + dc
        # The center's immediate 3 arm is transparent to its own ray.
        if 0 <= i < h and 0 <= j < w and original[i][j] == 3:
            i += dr
            j += dc
        while 0 <= i < h and 0 <= j < w:
            # Other crosses' arms/centers stop this ray.
            if original[i][j] != 0:
                break
            out[i][j] = color
            i += dr
            j += dc

    # Horizontal rays first; vertical rays take precedence at empty crossings.
    for r, c, color in centers:
        ray(r, c, 0, -1, color)
        ray(r, c, 0, 1, color)
    for r, c, color in centers:
        ray(r, c, -1, 0, color)
        ray(r, c, 1, 0, color)

    # A marker-only cross marks a protected vertical lane; the colored rays
    # continue on either side, but never paint empty cells in that column.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (original[r][c] == 0 and original[r - 1][c] == 3
                    and original[r + 1][c] == 3 and original[r][c - 1] == 3
                    and original[r][c + 1] == 3):
                for i in range(h):
                    if original[i][c] == 0:
                        out[i][c] = 0
    return out
